// Loads the bundled, compact Dota 2 VScript API (generated by scripts/build-api.mjs).

import { readFile } from "node:fs/promises";
import { ApiDatasetMetadata, ApiVersionSelection, currentApiMetadata, resolveApiFile, validateApiMetadata } from "./version.js";

export interface ApiArg {
  name: string;
  type: string;
  description?: string;
}

export interface ApiFunction {
  name: string;
  signature: string;
  args: ApiArg[];
  returns: string;
  description?: string;
  available?: "server" | "client" | "both";
}

export interface ApiClass {
  name: string;
  clientName?: string;
  extends?: string;
  description?: string;
  /** Inheritance may come from a separately identified historical reference. */
  inheritanceSource?: string;
  methods: ApiFunction[];
}

export interface ApiEnumMember {
  name: string;
  value?: number | string;
  description?: string;
}

export interface ApiEnum {
  name: string;
  kind: "enum" | "constant";
  value?: number | string;
  available?: string;
  members?: ApiEnumMember[];
}

export interface ApiData {
  classes: ApiClass[];
  functions: ApiFunction[];
  enums: ApiEnum[];
  generatedAt?: string;
  metadata: ApiDatasetMetadata;
}

const cache = new Map<string, Promise<ApiData>>();

export async function loadApi(version?: ApiVersionSelection): Promise<ApiData> {
  const selected = await resolveApiFile("vscript", version);
  let data = cache.get(selected.file);
  if (!data) {
    data = readFile(selected.file, "utf8").then((text) => {
      const parsed = JSON.parse(text) as ApiData;
      if (!Array.isArray(parsed.classes) || !Array.isArray(parsed.functions) || !Array.isArray(parsed.enums)) {
        throw new Error("Invalid VScript API dataset.");
      }
      parsed.metadata = validateApiMetadata(
        parsed.metadata ?? (selected.version === "current" ? currentApiMetadata("vscript", parsed.generatedAt) : undefined),
        selected.version, "vscript",
      );
      return parsed;
    });
    cache.set(selected.file, data);
    void data.catch(() => { cache.delete(selected.file); });
  }
  return data;
}
